#include <stdio.h>
#include <stdlib.h>
#define GOLD 0
int main(void) {
    int n;
    if (scanf("%d", &n) != 1) return 1;
    int *values = malloc((size_t)n * sizeof *values);
    if (!values) return 1;
    for (int i = 0; i < n; i++) if (scanf("%d", &values[i]) != 1) { free(values); return 1; }
#if GOLD
    int m;
    if (scanf("%d", &m) != 1) { free(values); return 1; }
    int *grown = realloc(values, (size_t)(n + m) * sizeof *values);
    if (!grown) { free(values); return 1; }
    values = grown;
    for (int i = n; i < n + m; i++) if (scanf("%d", &values[i]) != 1) { free(values); return 1; }
    n += m;
#endif
    int sum = 0, low = values[0], high = values[0];
    for (int i = 0; i < n; i++) {
        sum += values[i];
        if (values[i] < low) low = values[i];
        if (values[i] > high) high = values[i];
    }
#if GOLD
    printf("count=%d ", n);
#endif
    printf("sum=%d min=%d max=%d\n", sum, low, high);
    free(values);
    return 0;
}

